import{_ as a}from"./chunks/hub.pc.ko.D5LMmVxq.js";import{_ as t,o as e,c as i,a5 as r}from"./chunks/framework.BjM_ivYE.js";const u=JSON.parse('{"title":"2. 컨트롤러 & Wi-Fi 연결","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/guides/common/controller-wifi-connect.md","filePath":"ko/guides/common/controller-wifi-connect.md","lastUpdated":1789971982000}'),n={name:"ko/guides/common/controller-wifi-connect.md"};function c(l,o,s,m,d,h){return e(),i("div",null,[...o[0]||(o[0]=[r('<h1 id="_2-컨트롤러-wi-fi-연결" tabindex="-1">2. 컨트롤러 &amp; Wi-Fi 연결 <a class="header-anchor" href="#_2-컨트롤러-wi-fi-연결" aria-label="Permalink to &quot;2. 컨트롤러 &amp; Wi-Fi 연결&quot;">​</a></h1><p><strong>목표:</strong> 컨트롤러를 로봇 Wi-Fi에 연결하고, RBQ 앱을 로봇에 연결한 뒤 자동 기동을 완료하여 로봇이 동작 가능한 상태로 만듭니다.</p><p><strong>사전 조건:</strong> <a href="/RBQ/ko/guides/common/initial-pose.html">초기 자세 설정 및 전원 켜기</a>가 먼저 완료되어야 합니다 — 로봇이 켜져 있고 초기화된 상태여야 합니다.</p><h2 id="_1단계-wi-fi-연결" tabindex="-1">1단계: Wi-Fi 연결 <a class="header-anchor" href="#_1단계-wi-fi-연결" aria-label="Permalink to &quot;1단계: Wi-Fi 연결&quot;">​</a></h2><p>로봇은 <code>RBQ_{XX}</code>(XX는 기기마다 다름) 이름의 Wi-Fi 접속 지점을 냅니다. 컨트롤러(Steam Deck, 태블릿, PC)를 이 망에 연결합니다.</p><p>앱을 켜면 <strong>허브</strong>가 나오고, 로봇 이름 뒤의 상태줄이 지금 망이 맞는지 알려 줍니다.</p><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+a+'" alt="허브 — 로봇 이름과 상태줄" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ 허브 ]</figcaption></figure><ol><li><strong>상태줄 읽기</strong> - <code>로봇 WiFi에 연결하세요</code>는 저장된 로봇이 아직 없다는 뜻이고, <code>로봇 WiFi가 아닙니다</code>는 이 기기가 다른 망에 있다는 뜻입니다. 앱이 로봇의 WiFi를 알면 어느 망으로 바꿀지까지 표시합니다.</li><li><strong>로봇 네트워크 선택</strong> - Linux 데스크탑·Steam Deck에서는 상태줄 옆 <code>WiFi 전환</code>이 그 망에 바로 붙거나 앱 안의 목록을 열어 <code>RBQ_{XX}</code>를 고르게 합니다. Android는 <code>WiFi 설정</code>, iOS·웹은 기기의 Wi-Fi 설정에서 붙습니다. (목록에 보이지 않으면 로봇 전원과 Wi-Fi 동작 상태를 확인하세요.)</li><li><strong>연결 확인</strong> - 로봇 이름 앞의 점이 초록으로 바뀌면 됩니다.</li></ol><p>자세한 절차는 <a href="/RBQ/ko/manual/operation/controller-wifi-connect.html#wifi">컨트롤러와 Wi-Fi 연결</a>에 있습니다.</p><h2 id="connect" tabindex="-1">2단계: 앱을 로봇에 연결 <a class="header-anchor" href="#connect" aria-label="Permalink to &quot;2단계: 앱을 로봇에 연결 {#connect}&quot;">​</a></h2><p>RBQ 앱을 열어 로봇에 연결합니다. 로봇 IP 입력, 연결, 연결 상태 확인 절차는 <strong><a href="/RBQ/ko/manual/gui/connection.html">연결</a></strong> 페이지에 설명되어 있습니다.</p><h2 id="auto-start" tabindex="-1">3단계: 자동 기동 <a class="header-anchor" href="#auto-start" aria-label="Permalink to &quot;3단계: 자동 기동 {#auto-start}&quot;">​</a></h2><p>제어 화면의 자동 기동 시퀀스로 로봇 소프트웨어와 상태를 한 번에 올립니다. 시퀀스와 각 항목의 완료 확인 방법은 <strong><a href="/RBQ/ko/manual/gui/control-home.html">제어 홈</a></strong> 문서를 참고하세요. 항목이 실패하면 주변에 사람이 없는지 확인한 뒤 <a href="/RBQ/ko/manual/safety/emergency-stop-procedures.html">비상 정지 절차</a>를 숙지하고 <a href="/RBQ/ko/manual/safety/general-safety-warning-precautions.html">일반 안전 수칙</a>을 준수하세요. 문제가 계속되면 <a href="/RBQ/ko/manual/support/">기술지원 요청</a> 페이지에서 안내에 따라 Rainbow Robotics에 연락하세요.</p><h2 id="다음-단계" tabindex="-1">다음 단계 <a class="header-anchor" href="#다음-단계" aria-label="Permalink to &quot;다음 단계&quot;">​</a></h2><p>로봇이 연결되어 조작할 수 있는 상태입니다. 앱 화면 구성과 버튼은 <strong><a href="/RBQ/ko/manual/gui/introduction.html">RBQ 앱</a></strong> · <strong><a href="/RBQ/ko/manual/gui/control-home.html">제어 홈</a></strong> · <strong><a href="/RBQ/ko/manual/gui/motion-commands.html">모션 명령</a></strong> 에 정리되어 있습니다.</p><p>운용을 마친 뒤의 절차는 이어서 보세요:</p><p><strong><a href="/RBQ/ko/guides/common/charging.html">→ 3. 충전</a></strong></p>',17)])])}const f=t(n,[["render",c]]);export{u as __pageData,f as default};
